code='''def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])

    # A horizontal 5-bar marks the width of a region. Repeat the color
    # sequence immediately below its left end across that width.
    r = 0
    while r < h:
        c = 0
        while c < w:
            if a[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and a[r][c] == 5:
                c += 1
            end = c
            if r + 1 < h and a[r + 1][start] not in (0, 5):
                seq = []
                rr = r + 1
                while rr < h and a[rr][start] not in (0, 5):
                    seq.append(a[rr][start])
                    rr += 1
                for rr in range(r + 1, min(h, r + 1 + len(seq))):
                    for cc in range(start, end):
                        if a[rr][cc] == 0:
                            a[rr][cc] = seq[rr - (r + 1)]
        r += 1

    # A vertical 5-bar marks the height of a region. The colored rows at
    # its lower end form a repeating tile extending to the bar's right.
    c = 0
    while c < w:
        r = 0
        while r < h:
            if a[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and a[r][c] == 5:
                r += 1
            end = r
            # Find the colored block touching the bottom of this guide.
            block_start = end
            block_end = end
            if end < h and c + 1 < w and a[end][c + 1] not in (0, 5):
                block_start = end
                block_end = end + 1
            elif end - 1 >= start and c + 1 < w and a[end - 1][c + 1] not in (0, 5):
                block_end = end
                block_start = end - 1
                while block_start > start and a[block_start - 1][c + 1] not in (0, 5):
                    block_start -= 1
            else:
                block_start = block_end = end
            if block_start < block_end:
                seq = [a[rr][c + 1:] for rr in range(block_start, block_end)]
                for rr in range(start, end):
                    for j, cc in enumerate(range(c + 1, w)):
                        if a[rr][cc] == 0:
                            a[rr][cc] = seq[(rr - start) % len(seq)][j]
        c += 1
    return a
